package org.sleepwell.app;

import android.app.*;import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import org.junit.runner.RunWith;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;

/** Forces actual private worker completion before the next render, without timing sleeps or output. */
@RunWith(AndroidJUnit4.class)
public final class DiaryTerminalStateTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();DiaryActivity activity;
    void completeBeforeRender(Runnable operation){i.runOnMainSync(()->{activity.waiting=true;operation.run();try{activity.job.worker.submit(()->{}).get(3,TimeUnit.SECONDS);}catch(Exception failure){throw new AssertionError("Private diary worker did not complete",failure);}assertFalse(activity.job.state.busy);activity.render();assertFalse("Terminal state must settle even if first render sees it",activity.waiting);});}
    void edit(DiaryStore.Entry entry){i.runOnMainSync(()->{activity.id=entry.id;activity.revision=entry.updated;activity.title=entry.title;activity.text=entry.text;activity.editing=true;activity.render();});}
    @Test public void fastSaveErrorAndDeleteAlwaysSettleBeforeTheDrawnStateIsPinned()throws Exception{String name="diary-terminal-"+UUID.randomUUID();DiaryStore.Factory old=DiaryStore.factory,factory=context->new DiaryStore(context,name);Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());try{DiaryStore.factory=factory;try(DiaryStore store=factory.open(c)){store.save("",0,"Original",DiaryStorageTest.TEXT,System.currentTimeMillis());}activity=(DiaryActivity)i.startActivitySync(new Intent(c,DiaryActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));DiaryJobs.drain(factory);DiaryStore.Entry entry;try(DiaryStore store=factory.open(c)){entry=store.entries().get(0);}edit(entry);completeBeforeRender(()->activity.job.save(entry.id,entry.updated,"Fast saved",DiaryStorageTest.TEXT));i.runOnMainSync(()->assertFalse(activity.editing));DiaryStore.Entry updated;try(DiaryStore store=factory.open(c)){updated=store.entries().get(0);assertEquals("Fast saved",updated.title);}edit(updated);completeBeforeRender(()->activity.job.save(updated.id,updated.updated-1,"Rejected stale edit",DiaryStorageTest.TEXT));i.runOnMainSync(()->{assertTrue("An error preserves the editable draft",activity.editing);assertFalse(activity.job.state.error.isEmpty());});try(DiaryStore store=factory.open(c)){assertEquals("Fast saved",store.entries().get(0).title);}completeBeforeRender(()->activity.job.delete(updated.id,updated.updated));i.runOnMainSync(()->{assertFalse(activity.editing);assertTrue(activity.job.state.rows.isEmpty());assertEquals(0,activity.job.state.total);});try(DiaryStore store=factory.open(c)){assertEquals(0,store.count());}assertEquals(original,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}finally{if(activity!=null)i.runOnMainSync(activity::finish);i.waitForIdleSync();DiaryJobs.drain(factory);DiaryJobs.forget(factory);DiaryStore.factory=old;c.deleteDatabase(name);}}
}
